def _jet(g,inp,paths,owner,t,*,allow_taper=False,compound=False,continuations=False,port_paths=False,span_compounds=False,chain_sides=False,interpolation=False):
    node=g.node('GeometryNodeGroup','Analytic boundary jet on already prepared original paths')
    node.node_tree=charts.build(external_ratio=True,prepared_paths=True,allow_taper=allow_taper,compound=compound,continuations=continuations,port_paths=port_paths,span_compounds=span_compounds,chain_sides=chain_sides,interpolation=interpolation)
    for key,value in (('Index',owner),('t',t),('v',0.),
                      ('Depth Ratio',1.),('Ratio Derivative',0.),('Boundary Valid',inp.outputs['Input Valid'])):
        g.bind(value,node.inputs[key])
    if chain_sides:
        for key in ('Chain Pieces','Chain Paths'):g.bind(inp.outputs[key],node.inputs[key])
    else:
        for key,value in zip(('Path A','Path B'),paths):g.bind(value,node.inputs[key])
    for key in ('Corners','Mouths'):g.bind(inp.outputs[key],node.inputs[key])
    if span_compounds:g.bind(paths[2],node.inputs['Path Middle'])
    return node


def _mouth_distance(g,mouths,side,*,interpolation=False):
    """Squared XY distance to the complete physical mouth segment."""
    center=c._vec(g,c._read(g,mouths,'st_cj_position',side,'FLOAT_VECTOR'))
    right=c._right(c._vec(g,c._read(g,mouths,'st_cj_tangent',side,'FLOAT_VECTOR')))
    half=.5*c._read(g,mouths,'st_cj_width',side)
    delta=c._sub(c._vec(g,g.position()),center)
    lateral=c.bounded(g,c._dot(delta,right),-half,half)
    distance=c._sub(delta,c._scale(right,lateral))
    if interpolation:
        from .curved_exact_profile_nodes import mouth_axis
        axis=mouth_axis(g,mouths,side)
        parameter=c.bounded(g,c._dot(delta,axis)/g.math('MAXIMUM',c._dot(axis,axis),1e-12),-half,half)
        distance=c._pick(g,c._read(g,mouths,'st_cj_polyline',side,'BOOLEAN'),c._sub(delta,c._scale(axis,parameter)),distance)
    return c._dot(distance,distance)


