def _recover_curb_projections(g,inp,paths,owner,query,satisfied,**options):
    """Bracket failed projections on each original curb, independently.

    Newton can oscillate across a short positive-curvature corner when the
    query lies beyond its focal radius. The adjacent curb pieces still have
    valid stationary projections. Only a positive-to-negative residual bracket
    is refined, at most 24 times; every candidate must meet the original
    residual/jet checks. Accepted Newton/analytic results are retained exactly.
    The two external curb intervals also exist on compound span sides; their
    middle interval can contain several arcs or a retained internal curb.
    This recovery uses only the two external intervals. It is not a general
    closest-point certification of every compound piece.
    """
    point=c._vec(g,g.position())
    current=_jet(g,inp,paths,owner,c.named(g,'_ch_t'),**options)
    la,lc,lb=[c.V(g,current.outputs['Length '+key]) for key in ('A','Arc','B')]
