    geo=c._store(g,geo,'_chr_result',c.named(g,'_ch_t'))
    def evaluate(t):
        jet=_jet(g,inp,paths,owner,t,**options)
        delta=c._sub(point,c._vec(g,jet.outputs['Outer']))
        return c._dot(delta,c._vec(g,jet.outputs['Tangent'])),c._dot(delta,delta),jet.outputs['Valid']
    for lower,upper in ((0.,la/total),((la+lc)/total,1.)):
        rlo,_,vlo=evaluate(lower);rhi,_,vhi=evaluate(upper)
        bracket=(1.-satisfied)*c.V(g,vlo)*c.V(g,vhi)
        bracket=bracket*g.math('GREATER_THAN',rlo,-1e-30)*g.math('LESS_THAN',rhi,1e-30)
        prefer_hi=g.math('LESS_THAN',g.math('ABSOLUTE',rhi),g.math('ABSOLUTE',rlo))
        for key,value,kind in (('lo',lower,'FLOAT'),('hi',upper,'FLOAT'),('bracket',bracket,'BOOLEAN'),
            ('best_t',c.choose(g,prefer_hi,upper,lower),'FLOAT'),
            ('error',g.math('MINIMUM',g.math('ABSOLUTE',rlo),g.math('ABSOLUTE',rhi)),'FLOAT')):
            geo=c._store(g,geo,'_chr_'+key,value,kind)
        ri=g.node('GeometryNodeRepeatInput','Bracketed recovery on one original curb portion')
        ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
        g.bind(geo,ri.inputs['Geometry']);ri.inputs['Iterations'].default_value=24
        lo=c.named(g,'_chr_lo');hi=c.named(g,'_chr_hi');mid=.5*(lo+hi)
        residual,_,_=evaluate(mid);error=g.math('ABSOLUTE',residual)
        improve=g.math('LESS_THAN',error,c.named(g,'_chr_error'))
        fields=(('next_lo',c.choose(g,g.math('GREATER_THAN',residual,0.),mid,lo)),
                ('next_hi',c.choose(g,g.math('LESS_THAN',residual,0.),mid,hi)),
                ('next_t',c.choose(g,improve,mid,c.named(g,'_chr_best_t'))),
                ('next_error',g.math('MINIMUM',error,c.named(g,'_chr_error'))))
        refined=ri.outputs['Geometry']
        for key,value in fields:refined=c._store(g,refined,'_chr_'+key,value)
        for key,source in (('lo','next_lo'),('hi','next_hi'),('best_t','next_t'),('error','next_error')):
            refined=c._store(g,refined,'_chr_'+key,c.named(g,'_chr_'+source))
        g.bind(refined,ro.inputs['Geometry']);geo=ro.outputs['Geometry']
        station=c.named(g,'_chr_best_t');residual,distance,valid=evaluate(station)
        use=c.named(g,'_chr_bracket','BOOLEAN')*c.V(g,valid)
        use=use*g.math('LESS_THAN',g.math('ABSOLUTE',residual),PROJECTION_TOLERANCE)
        use=use*g.math('LESS_THAN',distance,c.named(g,'_chr_distance'))
        geo=c._store(g,geo,'_chr_next_result',c.choose(g,use,station,c.named(g,'_chr_result')))
