    for key in ('Valid','Projection Valid','Bounds Valid','Charts Agree'):g.socket(key,'NodeSocketBool','OUTPUT')
    inp=g.node('NodeGroupInput');mouths=inp.outputs['Mouths'];depths=inp.outputs['Depths']
