    ro=g.node('GeometryNodeRepeatOutput');ri.pair_with_output(ro)
    g.bind(geo,ri.inputs['Geometry']);g.bind(c.choose(g,valid,count,0,'INT'),ri.inputs['Iterations'])
    owner=c.V(g,ri.outputs['Iteration']);nxt=g.math('MODULO',owner+1.,count)
    # Certification and source preparation are outside the Newton iteration.
    indices=(owner,nxt)
    if span_compounds:indices+=(c._read(g,inp.outputs['Corners'],'st_pc_mid_port',owner,'INT'),)
    sources=[] if chain_sides else [boundary._source(g,inp,index,port_paths=port_paths,interpolation=interpolation) for index in indices]
    tables=[boundary._table(g,source) for source in sources];paths=[table.outputs['Geometry'] for table in tables]
