    t=c.named(g,'_ch_t');jet=_jet(g,inp,paths,owner,t,allow_taper=tapered,compound=compound,continuations=continuations,port_paths=port_paths,span_compounds=span_compounds,chain_sides=chain_sides,interpolation=interpolation)
    point=c._vec(g,g.position());outer=c._vec(g,jet.outputs['Outer']);tangent=c._vec(g,jet.outputs['Tangent'])
    normal=c._vec(g,jet.outputs['Normal']);turn=c.V(g,jet.outputs['Turn'])
