    query=no.outputs['Geometry'];t=c.named(g,'_ch_t');jet=_jet(g,inp,paths,owner,t,allow_taper=tapered,compound=compound,continuations=continuations,port_paths=port_paths,span_compounds=span_compounds,chain_sides=chain_sides,interpolation=interpolation)
