    inward=c._dot(delta,c._vec(g,jet.outputs['Normal']))
    lookup=g.node('GeometryNodeGroup');lookup.node_tree=spline.evaluate()
    for key,value in (('Geometry',depths),('Index',owner),('t',t),('Input Valid',inp.outputs['Input Valid'])):
        g.bind(value,lookup.inputs[key])
    width=c.V(g,jet.outputs['Nominal Depth'])*c.V(g,lookup.outputs['Ratio'])
    tol=PROJECTION_TOLERANCE;projected=g.math('LESS_THAN',g.math('ABSOLUTE',residual),tol)
    before=g.math('LESS_THAN',t,1e-7)*g.math('LESS_THAN',residual,tol)
    after=g.math('GREATER_THAN',t,1.-1e-7)*g.math('GREATER_THAN',residual,-tol)
    projection_ok=g.math('MAXIMUM',projected,g.math('MAXIMUM',before,after))
    projection_ok=projection_ok*path_ok*c.V(g,jet.outputs['Valid'])*c.V(g,lookup.outputs['Valid'])
    if chain_sides:projection_ok=g.math('MAXIMUM',remote,projection_ok)
    inside=projected*g.math('GREATER_THAN',width,1e-7)*g.math('GREATER_THAN',inward,-tol)*g.math('LESS_THAN',inward,width+tol)
    if chain_sides:inside=inside*(1.-remote)
