    previous=c.named(g,'st_ch_fraction');owners=c.named(g,'st_ch_owners','INT')
    mismatch=g.math('GREATER_THAN',g.math('ABSOLUTE',previous-fraction),1e-4)
    if tapered:
        lift=c.V(g,jet.outputs['Edge Rise'])*(1.-fraction);previous_lift=c.named(g,'st_ch_lift')
        mismatch=g.math('MAXIMUM',mismatch,g.math('GREATER_THAN',g.math('ABSOLUTE',previous_lift-lift),1e-5))
    conflict=inside*g.math('GREATER_THAN',owners,.5)*mismatch
    # Capture all update fields before changing the attributes they reference.
    query=c._store(g,query,'_ch_fraction',c.choose(g,inside,fraction,previous))
    query=c._store(g,query,'_ch_conflict',g.math('MAXIMUM',c.named(g,'st_ch_conflict','BOOLEAN'),conflict),'BOOLEAN')
    if tapered:query=c._store(g,query,'_ch_lift',c.choose(g,inside,lift,previous_lift))
    query=c._store(g,query,'st_ch_fraction',c.named(g,'_ch_fraction'))
    query=c._store(g,query,'st_ch_conflict',c.named(g,'_ch_conflict','BOOLEAN'),'BOOLEAN')
    if tapered:query=c._store(g,query,'st_ch_lift',c.named(g,'_ch_lift'))
