    amplitude=c.bounded(g,amplitude,lowest,highest)
    physical=datum+amplitude*c.named(g,'st_ch_fraction')
    if tapered:physical=physical+c.named(g,'st_ch_lift')
    pinned=c.named(g,'st_cq_height_pinned','BOOLEAN')
    physical=c.choose(g,pinned,c.named(g,'st_cq_pinned_height'),physical)
    projection=valid*c._stat(g,geo,c.choose(g,pinned,1.,c.named(g,'st_ch_projection_ok','BOOLEAN')))
    agree=valid*c._stat(g,geo,c.choose(g,pinned,1.,1.-c.named(g,'st_ch_conflict','BOOLEAN')))
    ceiling=datum+highest
    bounded=g.math('GREATER_THAN',physical,datum-1e-6)*g.math('LESS_THAN',physical,ceiling+1e-6)
    bounded=bounded*g.math('GREATER_THAN',denominator,1e-20)
    bounds=valid*c._stat(g,geo,bounded)
    exaggeration=c.V(g,inp.outputs['Height Exaggeration'])
    good=projection*agree*bounds*g.math('GREATER_THAN',exaggeration,-1e-7)*g.math('LESS_THAN',exaggeration,1e6)
    if tapered:physical=c.bounded(g,physical,datum,ceiling)
    for key,value,kind in (('height',physical,'FLOAT'),('amplitude',amplitude,'FLOAT'),('valid',good,'BOOLEAN')):
        geo=c._store(g,geo,'st_ch_'+key,value,kind)
    x,y,_=g.separate(g.position());raised=g.setpos(geo,g.xyz(x,y,datum+(c.named(g,'st_ch_height')-datum)*exaggeration))
    out=g.node('NodeGroupOutput')
    for key,value in (('Geometry',boundary._empty(g,raised,good)),('Inspection Geometry',raised),('Valid',good),
                      ('Projection Valid',projection),('Bounds Valid',bounds),('Charts Agree',agree)):
        g.bind(value,out.inputs[key])
    return g.g
